🐛 Bug
Mutable dictionary string type stops working after assigning value in dictionary. The line  print torch.ops.map_rasterizer_utils.ends_with(key, '_cont') works when called before assigning the key to the frame_dictionary but not after.
To Reproduce
Steps to reproduce the behavior:

Python class that calls c++ custom ops

class Inference(torch.jit.ScriptModule):
    def __init__(self):
        super(Inference, self).__init__(optimize=False)

    @torch.jit.script_method
    def forward(self, input_dict):
        # type: (Dict[str, torch.Tensor]) -> None

        frame_dictionary = torch.jit.annotate(Dict[str, torch.Tensor], {})
        keys = torch.jit.annotate(List[str], [
            'maps_key'
        ])

        for key in keys:
            value = input_dict[key]
            frame_dictionary[key] = value
            print torch.ops.map_rasterizer_utils.ends_with(key, '_cont')


def main():
    input_dict = {
        "maps_key": torch.zeros(1)
    }
    jit_model = Inference()
    jit_model.forward(input_dict)
    jit_model.save("/tmp/model/jitbug.pt")

if __name__ == "__main__":
    main()


C++ method:

int64_t ends_with(std::string input, std::string suffix)
{
    bool result = false;
    if (input.length() >= suffix.length())
    {
        result = (0 == input.compare(input.length() - suffix.length(), suffix.length(), suffix));
    }
    return result ? 1 : 0;
}

static auto registry = torch::jit::RegisterOperators("map_rasterizer_utils::ends_with", &ends_with);

